CREATE TABLE tantu.provider_schedule(connection_id uuid PRIMARY KEY REFERENCES tantu.provider_connections ON DELETE CASCADE,workspace_id uuid NOT NULL,user_id uuid NOT NULL,active boolean NOT NULL,due_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION tantu.provider_schedule_changed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,tantu AS $$ BEGIN INSERT INTO tantu.provider_schedule(connection_id,workspace_id,user_id,active,due_at) VALUES(NEW.id,NEW.workspace_id,NEW.user_id,NEW.status='active',coalesce(NEW.retry_at,now())) ON CONFLICT(connection_id) DO UPDATE SET active=excluded.active,due_at=CASE WHEN NOT excluded.active THEN 'infinity'::timestamptz WHEN NEW.retry_at IS NOT NULL THEN NEW.retry_at ELSE least(tantu.provider_schedule.due_at,now()+interval '5 minutes') END; RETURN NEW; END $$;
CREATE TRIGGER provider_schedule_changed AFTER INSERT OR UPDATE ON tantu.provider_connections FOR EACH ROW EXECUTE FUNCTION tantu.provider_schedule_changed();
ALTER TABLE tantu.provider_connections NO FORCE ROW LEVEL SECURITY;
INSERT INTO tantu.provider_schedule(connection_id,workspace_id,user_id,active) SELECT id,workspace_id,user_id,status='active' FROM tantu.provider_connections;
ALTER TABLE tantu.provider_connections FORCE ROW LEVEL SECURITY;
REVOKE ALL ON tantu.provider_schedule FROM PUBLIC;
CREATE FUNCTION tantu.claim_provider_reconciliation() RETURNS TABLE(connection_id uuid,workspace_id uuid,user_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,tantu AS $$ UPDATE tantu.provider_schedule s SET due_at=now()+interval '5 minutes' WHERE s.connection_id IN(SELECT p.connection_id FROM tantu.provider_schedule p WHERE p.active AND p.due_at<=now() AND EXISTS(SELECT 1 FROM tantu.memberships m WHERE m.workspace_id=p.workspace_id AND m.user_id=p.user_id AND m.active) ORDER BY p.due_at LIMIT 10 FOR UPDATE SKIP LOCKED) RETURNING s.connection_id,s.workspace_id,s.user_id $$;
REVOKE ALL ON FUNCTION tantu.claim_provider_reconciliation(),tantu.provider_schedule_changed() FROM PUBLIC;
ALTER TABLE tantu.provider_cursors ADD updated_at timestamptz NOT NULL DEFAULT now();
CREATE TABLE tantu.provider_folders(workspace_id uuid NOT NULL,connection_id uuid NOT NULL,external_id text NOT NULL,name text NOT NULL,parent_id text,children_done boolean NOT NULL DEFAULT false,children_cursor text,cursor text,generation uuid NOT NULL DEFAULT gen_random_uuid(),synced_at timestamptz,seen_generation uuid NOT NULL,PRIMARY KEY(connection_id,external_id),FOREIGN KEY(workspace_id,connection_id) REFERENCES tantu.provider_connections(workspace_id,id));
CREATE TABLE tantu.provider_folder_scans(workspace_id uuid NOT NULL,connection_id uuid PRIMARY KEY,root_cursor text,root_done boolean NOT NULL DEFAULT false,generation uuid NOT NULL DEFAULT gen_random_uuid(),completed_at timestamptz,FOREIGN KEY(workspace_id,connection_id) REFERENCES tantu.provider_connections(workspace_id,id));
CREATE TABLE tantu.provider_subscriptions(workspace_id uuid NOT NULL,connection_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('mail','calendar')),external_id text NOT NULL,client_state text NOT NULL,resource_id text,expires_at timestamptz NOT NULL,PRIMARY KEY(connection_id,kind),FOREIGN KEY(workspace_id,connection_id) REFERENCES tantu.provider_connections(workspace_id,id));
CREATE TABLE tantu.provider_notifications(workspace_id uuid NOT NULL,connection_id uuid NOT NULL,notification_id text NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(connection_id,notification_id),FOREIGN KEY(workspace_id,connection_id) REFERENCES tantu.provider_connections(workspace_id,id));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['provider_folders','provider_folder_scans','provider_subscriptions','provider_notifications'] LOOP EXECUTE format('ALTER TABLE tantu.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE tantu.%I FORCE ROW LEVEL SECURITY',t); EXECUTE format('CREATE POLICY connection_scope ON tantu.%I FOR ALL USING(workspace_id=tantu.tenant() AND EXISTS(SELECT 1 FROM tantu.provider_connections WHERE id=connection_id)) WITH CHECK(workspace_id=tantu.tenant() AND EXISTS(SELECT 1 FROM tantu.provider_connections WHERE id=connection_id))',t); END LOOP; END $$;
